"""Recursive field-level diff of two JSON documents. Reports ADDED / REMOVED / CHANGED (value or type) / LEN.
Usage: python3 field_diff.py before.json after.json [--skip-top key,key]"""
import json, sys, collections
a = json.load(open(sys.argv[1])); b = json.load(open(sys.argv[2]))
skip = set(sys.argv[4].split(',')) if len(sys.argv) > 4 and sys.argv[3] == '--skip-top' else set()
diffs = []
def walk(x, y, path):
    if type(x) is not type(y):
        diffs.append(('CHANGED_TYPE', path, x, y)); return
    if isinstance(x, dict):
        for k in sorted(set(x) | set(y)):
            if k not in y: diffs.append(('REMOVED', path + [k], x[k], None))
            elif k not in x: diffs.append(('ADDED', path + [k], None, y[k]))
            else: walk(x[k], y[k], path + [k])
    elif isinstance(x, list):
        if len(x) != len(y): diffs.append(('LEN', path, len(x), len(y)))
        for i, (p, q) in enumerate(zip(x, y)): walk(p, q, path + [i])
    elif x != y:
        diffs.append(('CHANGED', path, x, y))
for k in sorted(set(a) | set(b)):
    if k in skip: continue
    if k not in b: diffs.append(('REMOVED', [k], a[k], None))
    elif k not in a: diffs.append(('ADDED', [k], None, b[k]))
    else: walk(a[k], b[k], [k])
def leafkey(p): return next((s for s in reversed(p) if isinstance(s, str)), None)
summary = {
  'total_entries': len(diffs),
  'by_kind': dict(collections.Counter(d[0] for d in diffs)),
  'by_top_section': dict(collections.Counter(str(d[1][0]) for d in diffs)),
}
c = collections.Counter((d[0], str(d[1][0]), leafkey(d[1]), json.dumps(d[3], sort_keys=True)) for d in diffs)
summary['by_kind_section_key_after_value'] = [{'kind': k[0], 'section': k[1], 'key': k[2], 'after_value': json.loads(k[3]), 'count': n} for k, n in sorted(c.items())]
summary['entries'] = [{'kind': d[0], 'path': d[1], 'before': d[2], 'after': d[3]} for d in diffs]
print(json.dumps(summary, indent=1, sort_keys=True, ensure_ascii=False))
